<template><main class="login-page"><div class="login-brand"><span><PackageOpen :size="20"/></span> nexstock</div><section class="login-card"><div class="login-mark"><PackageOpen :size="21"/></div><h1>Welcome back</h1><p>Sign in to your Nexstock workspace.</p><form @submit.prevent="submit"><label>Email address<input v-model="email" type="email" autocomplete="username" placeholder="you@company.com" required/></label><label>Password<input v-model="password" type="password" autocomplete="current-password" placeholder="Enter your password" required/></label><div v-if="error" class="login-error">{{error}}</div><button class="button primary login-submit" :disabled="loading">{{loading?'Signing in…':'Sign in'}} <ArrowRight :size="15"/></button></form><div class="login-demo"><LockKeyhole :size="14"/><span>Demo access: <b>admin@nexstock.local</b> · <b>Nexstock123!</b></span></div></section><footer>© {{new Date().getFullYear()}} Nexstock, Inc. <span>Secure inventory operations</span></footer></main></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {PackageOpen,ArrowRight,LockKeyhole} from 'lucide-vue-next';import {api} from '../services/api';const router=useRouter(),email=ref('admin@nexstock.local'),password=ref('Nexstock123!'),loading=ref(false),error=ref('');async function submit(){loading.value=true;error.value='';try{const{data}=await api.post('/auth/login',{email:email.value,password:password.value});localStorage.setItem('nexstock_token',data.token);localStorage.setItem('nexstock_user',JSON.stringify(data.user));await router.push('/');}catch{error.value='That email and password combination was not recognized.';}finally{loading.value=false;}}</script>
